/* N26 usage explanations derived from reviewed profile, shooting, melee and trait rules. Read-only. */
(function(){'use strict';
const R=()=>window.RULES_DATA||{},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${esc(en)}" data-i18n-ko="${esc(ko)}">${esc(en)}</span>`,P=pair=>window.MMRuleTerms?MMRuleTerms.prose(...pair,{edition:'n26'}):`<p>${L(...pair)}</p>`,edition=row=>String(row?.edition_slug||row?.edition||'').toLowerCase(),profiles=row=>['profiles','weaponProfiles','weapon_profiles'].map(k=>row?.[k]).find(v=>Array.isArray(v)&&v.length)||[],norm=s=>String(s||'').trim().toLowerCase(),trait=(p,name)=>window.MMRuleReference?.traitTokens(p.traits).some(t=>norm(t).replace(/\s*\(.*\)$/,'')===norm(name));
function resolve(item,ed){
 if(!item||String(ed||window.MMRuleReference?.currentEdition()).toLowerCase()!=='n26'||item.is_custom||item.customAssetId||item.profile_scope_unresolved||edition(item)&&edition(item)!=='n26')return null;
 const ids=[item.catalogId,item.presetId,item.id].filter(Boolean),all=R().equipment||[];
 for(const id of ids){const base=all.find(e=>e.id===id);if(base)return base.source_verified&&edition(base)==='n26'&&!base.profile_scope_unresolved?base:null;}
 if(item.catalogId||item.presetId)return null;
 const matches=all.filter(e=>e.source_verified&&edition(e)==='n26'&&[e.name,e.name_ko].some(n=>norm(n)===norm(item.name)));return matches.length===1&&!matches[0].profile_scope_unresolved?matches[0]:null;
}
function describe(item,options={}){
 const base=resolve(item,options.edition);if(!base)return null;
 const pp=profiles(base),own=options.profiles||profiles(item),rd=base.rule_data||{},extra=own.length&&(own.length!==pp.length||own.some(p=>!pp.some(b=>p.id&&b.id===p.id||norm(p.profile_name||p.name)===norm(b.profile_name||b.name)))||own.some(p=>{const b=pp.find(b=>p.id&&b.id===p.id||norm(p.profile_name||p.name)===norm(b.profile_name||b.name));return b&&['Combi','Lance-bomb','Melee','Heavy','Light','Additional Attacks'].some(t=>trait(p,t)!==trait(b,t));}));
 if(extra)return {base,kind:'modified',rows:[[['Profile scope','프로필 범위'],['This record has added or changed profiles. Do not assume that every displayed row belongs to the standard purchase; check the custom entry.','이 기록에는 추가·수정된 프로필이 있습니다. 표시된 모든 행이 표준 구매에 포함된다고 가정하지 말고 사용자 설정을 확인하세요.']]],profiles:pp,ruleIds:['n26-core-shooting']};
 const melee=pp.filter(p=>trait(p,'Melee')||norm(p.range_short)==='e'),ranged=pp.filter(p=>!melee.includes(p)),hasCombi=pp.some(p=>trait(p,'Combi')),lance=pp.some(p=>trait(p,'Lance-bomb'));
 const memberships=(R().fighterEquipment||[]).filter(x=>x.source_verified&&x.equipment_id===base.id),required=rd.requires_equipment_name||item.requires_weapon_names?.join(' / ')||[...new Set(memberships.flatMap(x=>x.requires_weapon_names||[]))].join(' / '),ammo=rd.is_ammunition||norm(base.equipment_type)==='ammunition'||/ammunition/i.test(base.equipment_category||base.category||'');
 let kind=rd.bundle_components?.length?'bundle':lance?'lance-bomb':hasCombi?'combi':melee.length&&ranged.length?ranged.some(p=>trait(p,'Light'))?'light-hybrid':'hybrid':pp.length>1?'ammunition':ammo?'additional-ammo':null;
 if(!kind)return null;
 const rows=[],add=(label,text)=>rows.push([label,text]),ruleIds=new Set(ranged.length?['n26-core-shooting','n26-core-out-of-ammo']:['n26-core-melee-sequence']);
 if(kind==='bundle'){
  add(['At purchase','구매할 때'],['This is a bundle of separate components, not a permanent choice of one displayed profile. Each component follows its own entry.','여러 구성품이 포함된 구매 묶음입니다. 표시 프로필 중 하나를 영구 선택하는 상품이 아니며, 구성품마다 자신의 규칙을 따릅니다.']);
  add(['Using the bundle','사용할 때'],['Use the relevant component for the declared action. Owning the bundle does not itself allow all components to attack simultaneously.','선언한 행동에 맞는 구성품을 사용합니다. 묶음을 보유했다는 이유만으로 모든 구성품의 동시 공격이 허용되지는 않습니다.']);
 }else if(kind==='lance-bomb'){
  add(['Profile transition','프로필 전환'],['Not a free choice: the first successful hit each battle uses Primed; all later hits use Spent. A miss does not consume the first successful hit.','자유 선택이 아닙니다. 전투마다 첫 성공한 명중은 프라임드, 이후의 명중은 스펜트로 처리합니다. 빗나간 공격만으로 첫 성공 명중을 소비하지 않습니다.']);
  add(['Reset','초기화 시점'],['This sequence restarts each battle, not each activation.','매 활성화가 아니라 다음 전투에 다시 시작합니다.']);
  ruleIds.add('official-003-weapontraits-lance-bomb');
 }else{
  if(kind==='additional-ammo'){
   add(['At purchase','구매할 때'],['This is additional ammunition for a compatible weapon. It is not a purchase of the base weapon. Obtain the required weapon and the ammunition separately.','호환 무기에 추가하는 별도 탄약입니다. 기본 무기를 구매하는 항목이 아니므로 필요한 무기와 탄약을 각각 확보해야 합니다.']);
  }else add(['At purchase','구매할 때'],['The standard item includes the profiles displayed here; you do not permanently choose just one when buying it. Separately listed ammunition is a separate purchase.','이 표준 장비에는 여기에 표시된 프로필이 포함됩니다. 구매할 때 하나로 영구 고정하지 않습니다. 별도 항목으로 판매되는 추가 탄약은 따로 구매합니다.']);
  if(kind==='hybrid'||kind==='light-hybrid'){
   add(['Ranged attack','사격할 때'],[ranged.length>1?'Choose one usable ranged profile when declaring each shot, before measuring and rolling. You may choose a different usable profile for a later attack.':'Declare the usable ranged profile for the shot; the melee profile is not an extra ranged attack.',ranged.length>1?'사격할 때마다 거리 측정·굴림 전 사격 선언 단계에 사용 가능한 원거리 프로필 1개를 고릅니다. 다음 공격에서는 사용 가능한 다른 프로필로 바꿀 수 있습니다.':'사격에는 사용 가능한 원거리 프로필을 선언합니다. 근접 행이 추가 사격 공격을 주는 것은 아닙니다.']);
   add(['Close combat','근접전에서는'],kind==='light-hybrid'?['Select Primary/Secondary weapons in the melee weapon-selection step. A Light profile may be used in melee under Light’s limits; resolve Additional Attacks by its own condition.','근접전의 무기 선택 단계에 프라이머리·세컨더리를 정합니다. 라이트 프로필은 라이트 제한에 따라 근접 사용이 가능하며, 추가 공격은 해당 특성의 별도 조건을 따릅니다.']:['Use an eligible Melee profile in the melee weapon-selection step. The ranged rows do not automatically become extra melee attacks.','근접전 무기 선택 단계에 사용할 수 있는 밀리 프로필을 사용합니다. 원거리 행들이 자동으로 추가 근접 공격이 되지는 않습니다.']);
   ruleIds.add('n26-core-melee-sequence');ruleIds.add('n26-core-melee-attack-dice');
   if(kind==='light-hybrid'){ruleIds.add('official-003-weapontraits-light');ruleIds.add('official-003-weapontraits-additional-attacks-x');}
  }else if(kind!=='combi')add(['Selection timing','선택 시점'],['Choose one usable ranged profile when declaring each shot, before measuring range or rolling. You may choose another usable profile for the next attack; do not switch after seeing the dice.','사격할 때마다 거리 측정·굴림 전 사격 선언 단계에 사용 가능한 원거리 프로필 1개를 고릅니다. 다음 공격에서는 바꿀 수 있지만 주사위를 본 뒤 바꾸지는 않습니다.']);
  if(kind==='combi'){
   add(['Combi exception','콤비 예외'],['During Shoot or Aimed Shot, declare one profile or both before rolling. Both must target the same model; apply −1 to each Hit roll and resolve simultaneously.','슛·에임드 샷에서 굴림 전에 하나 또는 둘 다 사용할지 선언합니다. 둘 다 사용하면 같은 모델을 대상으로 각 명중 굴림에 −1을 적용하고 동시에 해결합니다.']);
   ruleIds.add('official-003-weapontraits-combi');
  }else add(['Simultaneous use','동시 사용'],['Several rows are not permission to combine their Strength, AP, L or traits, or to fire all of them in one attack. A separate rule must explicitly allow simultaneous use.','행이 여러 개라고 S·AP·L·특성을 합산하거나 한 번의 공격으로 전부 발사하는 것은 아닙니다. 동시 사용은 별도 규칙의 명시적 허용이 필요합니다.']);
 }
 if(kind==='hybrid'||kind==='light-hybrid'){rows[0][1]=[`One item includes ${melee.length} melee and ${ranged.length} ranged profiles; you do not permanently choose just one at purchase. Separately sold ammunition still requires a separate purchase.`,`이 장비 한 개에 근접용 ${melee.length}개·원거리 ${ranged.length}개 프로필이 포함됩니다. 구매할 때 하나로 영구 고정하지 않습니다. 별도 판매되는 추가 탄약은 따로 구매합니다.`];}
 if(base.id==='official-001-equipment-cawdor-polearm-blunderbuss-with-grape-purgation-rounds')add(['Example for this weapon','이 무기의 사용 예'],['Declare grape rounds for one shot. For the next permitted shot, you may declare purgation rounds instead. In close combat use the melee polearm profile. These are not three attacks granted by buying one item.','이번 사격에는 그레이프 라운드를 선언하고, 다음에 사격할 수 있을 때는 퍼게이션 라운드로 바꿀 수 있습니다. 근접전에서는 폴암의 밀리 행을 사용합니다. 장비 하나를 샀다고 공격 세 번을 얻는 것은 아닙니다.']);
 if(ranged.length&&kind!=='bundle'&&kind!=='lance-bomb')add(['Out of Ammo','탄약이 고갈되면'],['Only the fired profile becomes Out of Ammo; other usable profiles remain available. One Reload restores one chosen profile. Jammed, Limited and Single Shot have their own stricter restrictions.','사용한 프로필만 아웃 오브 애모가 되며 다른 사용 가능한 프로필은 남습니다. 리로드 한 번은 선택한 프로필 하나를 복구합니다. 잼·리미티드·싱글 샷의 별도 제한은 따로 적용합니다.']);
 if(kind==='hybrid'&&melee.some(p=>trait(p,'Heavy'))&&!ranged.some(p=>trait(p,'Heavy'))){
  add(['Trait scope','특성이 적용되는 범위'],['Heavy and Unwieldy on the melee row apply to that row, not to every profile on this item. A ranged row without Heavy does not require Braced Shot merely because the polearm is Heavy.','근접 행의 헤비·언윌디를 모든 행에 옮겨 적용하지 않습니다. 헤비가 없는 원거리 행은 폴암이 헤비라는 이유만으로 브레이스드 샷을 요구하지 않습니다.']);ruleIds.add('official-003-weapontraits-heavy');
 }
 if(ranged.length&&kind!=='bundle'&&kind!=='lance-bomb'){add(['Action allowance','행동 횟수'],['Changing a profile does not grant another action. Normal action costs and the restriction on repeating a named action still apply unless a rule explicitly overrides them.','프로필 변경이 추가 행동을 주지는 않습니다. 별도 규칙의 예외가 없다면 정상 행동 비용과 같은 이름 행동의 반복 제한을 지켜야 합니다.']);ruleIds.add('n26-core-action-economy');}
 if(base.starred)add(['Weapon slots','휴대 무기 칸'],['A starred item normally occupies two weapon slots. Counting its profile rows does not count separate carried weapons; model/accessory exceptions still apply.','별표 장비는 기본적으로 무기 두 칸을 차지합니다. 프로필 행 수를 별도 휴대 무기 수로 세지 않으며 모델·액세서리 예외는 따로 적용합니다.']);
 if(base.starred)ruleIds.add('n26-core-weapon-slots');
 return {base,kind,rows,profiles:pp,melee,ranged,required,ruleIds:[...ruleIds]};
}
const titles={hybrid:['Melee + ranged modes','근접·사격 겸용'], 'light-hybrid':['Melee and Light weapon rules','근접·라이트 무기 구분'],ammunition:['Choose ammunition for each shot','사격마다 탄종 선택'],combi:['Choose a profile · Combi exception','프로필 선택·콤비 예외'],'lance-bomb':['Profile changes after the first hit','첫 성공 명중 후 프로필 전환'],bundle:['A bundle of components','구성품 구매 묶음'],'additional-ammo':['Additional ammunition · base weapon required','추가 탄약·기본 무기 필요'],modified:['Check the modified profile scope','수정된 프로필 범위 확인']};
function ruleButton(id){const row=[...(R().coreRules||[]),...(R().weaponTraits||[])].find(r=>r.id===id);if(!row?.source_verified)return '';const kind=(R().coreRules||[]).some(r=>r.id===id)?'coreRules':'weaponTraits';return `<button type="button" class="btn small" data-equipment-usage-rule="${esc(id)}" data-usage-kind="${kind}">${L(row.name,row.name_ko||row.name)}</button>`;}
const quick={
 hybrid:['Choose the profile for shooting or melee','사격·근접에 맞는 프로필 선택'],
 'light-hybrid':['Check melee / Light profile limits','근접·라이트 프로필 구분'],
 ammunition:['Choose one ammunition profile before each shot','사격 선언 때 탄종 1개 선택'],
 combi:['Firing both Combi profiles: −1 to each Hit roll','콤비 동시 사격: 각 명중 −1'],
 'lance-bomb':['First successful hit: Primed → later hits: Spent','첫 성공 명중: 프라임드 → 이후: 스펜트'],
 bundle:['Each component follows its own rules','구성품마다 개별 규칙 적용'],
 'additional-ammo':['Additional ammo · compatible weapon required','추가 탄약 · 호환 무기 필요'],
 modified:['Modified profiles · check their scope','수정 프로필 · 사용 범위 확인']
};
function markup(item,options={}){const d=describe(item,options);if(!d)return '';const visible=d.kind==='lance-bomb'||d.kind==='bundle'?d.rows.slice(0,1):d.rows.slice(0,2);return `<details class="equipment-usage" data-equipment-usage="${esc(d.base.id)}" data-usage-mode="${d.kind}"><summary><span class="equipment-usage-quick">${L(...quick[d.kind])}</span><span class="equipment-usage-toggle">${L('How to use','사용법')}<span class="equipment-usage-chevron" aria-hidden="true"></span></span></summary><div class="equipment-usage-body"><strong>${L(...titles[d.kind])}</strong>${visible.map(([label,text])=>`<p>${L(...text)}</p>`).join('')}${d.kind==='modified'?'':`<button type="button" class="equipment-usage-more" data-equipment-usage-open="${esc(d.base.id)}">${L('Full procedure & exceptions','전체 절차·예외 보기')}</button>`}</div></details>`;}

function profileLabel(profile,item,ed){const name=profile.profile_name||profile.name||item?.name||'',known=resolve(item,ed||window.MMRuleReference?.currentEdition());if(!known)return {name,ko:name,custom:true};const explicit=profile.profile_name_ko||(norm(profile.name)===norm(name)?profile.name_ko:null),ko=explicit&&/[가-힣]/.test(explicit)?explicit:window.UKI18n?.name(name)||name;return {name,ko,custom:false};}
function profileTitle(profile,item,ed,options={}){const label=profileLabel(profile,item,ed);if(label.custom)return `<span data-user-text>${esc(label.name)}</span>`;const known=resolve(item,ed||window.MMRuleReference?.currentEdition()),scope=trait(profile,'Melee')||norm(profile.range_short)==='e'?['Melee','근접용']:trait(profile,'Light')?['Ranged / Light in melee','사격·라이트 근접 사용']:['Ranged','사격용'];return L(label.name,label.ko)+(options.scope!==false&&profiles(known).length>1?` <small class="equipment-profile-scope">${L(...scope)}</small>`:'');}
function open(item,options={}){const d=describe(item,{edition:'n26',...options});if(!d)return false;const body=`<div class="equipment-usage-detail"><h3>${L(d.base.name,d.base.name_ko||d.base.name)}</h3>${P(titles[d.kind])}<dl>${d.rows.map(([label,text])=>`<div><dt>${L(...label)}</dt><dd>${P(text)}</dd></div>`).join('')}</dl>${d.required?`<p>${L('Required compatible weapon','필요한 호환 무기')}: ${L(d.required,window.UKI18n?.name(d.required)||d.required)}</p>`:''}<div class="equipment-usage-rules">${d.ruleIds.map(ruleButton).join('')}</div></div>`;return window.MMRuleReference.openContext('How to use this equipment',body,{nameKo:'장비 사용 방식과 선택 시점',activator:options.activator||document.activeElement,nested:!!document.querySelector('.mmrr-overlay')});}
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-equipment-usage-open],[data-equipment-usage-rule]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.equipmentUsageOpen){const item=(R().equipment||[]).find(r=>r.id===b.dataset.equipmentUsageOpen);if(item)open(item,{activator:b});}else window.MMRuleReference.open(b.dataset.usageKind,b.dataset.equipmentUsageRule,{edition:'n26',activator:b,nested:true});},true);
window.MMEquipmentUsage={describe,markup,profileLabel,profileTitle,open};
})();
